using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;

var builder = Host.CreateApplicationBuilder(args);

// Logging must go to stderr — stdout is reserved for JSON-RPC protocol messages.
builder.Logging.AddConsole(options =>
    options.LogToStandardErrorThreshold = LogLevel.Trace);

// Register services that tools need via DI.
builder.Services.AddHttpClient("Api", client =>
{
    client.BaseAddress = new Uri("https://jsonplaceholder.typicode.com");
});

// Register MCP server with stdio transport and auto-discover all tool classes.
builder.Services.AddMcpServer()
    .WithStdioServerTransport()
    .WithToolsFromAssembly();

await builder.Build().RunAsync();

using System.ComponentModel;
using System.Text.Json;
using Microsoft.Extensions.Logging;
using ModelContextProtocol.Server;

[McpServerToolType]
public class ApiTools(IHttpClientFactory httpClientFactory, ILogger<ApiTools> logger)
{
    [McpServerTool, Description("Get a post by its numeric ID from the REST API.")]
    public async Task<string> GetPost(
        [Description("The numeric ID of the post (1-100)")] int postId,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Fetching post {PostId}", postId);
        var client = httpClientFactory.CreateClient("Api");
        var json = await client.GetStringAsync($"/posts/{postId}", cancellationToken);
        return json;
    }

    [McpServerTool, Description("List all posts by a specific user ID.")]
    public async Task<string> GetPostsByUser(
        [Description("The user ID to filter posts by")] int userId,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Fetching posts for user {UserId}", userId);
        var client = httpClientFactory.CreateClient("Api");
        var json = await client.GetStringAsync($"/posts?userId={userId}", cancellationToken);
        return json;
    }

    [McpServerTool, Description("Create a new post via the REST API.")]
    public async Task<string> CreatePost(
        [Description("Title of the new post")] string title,
        [Description("Body content of the post")] string body,
        [Description("Author user ID")] int userId,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Creating post for user {UserId}", userId);
        var client = httpClientFactory.CreateClient("Api");
        var payload = JsonSerializer.Serialize(new { title, body, userId });
        var content = new StringContent(payload, System.Text.Encoding.UTF8, "application/json");
        var response = await client.PostAsync("/posts", content, cancellationToken);
        return await response.Content.ReadAsStringAsync(cancellationToken);
    }
}

